test('formatMoney EUR returns plain number', () => {
  const result = formatMoney(10000, 'EUR');

  assert.equal(result, '100.00');
});

test('formatMoney EUR no currency symbol', () => {
  const result = formatMoney(5000, 'EUR');

  assert.ok(!result.includes('€'));
  assert.ok(!result.includes('$'));
});

